-- Friendly event URLs (/e/<slug>) and the attendee's "My events" list. Additive only.
--
-- webinars.slug is unique and generated by the database from the title when a webinar is created. It never
-- changes afterwards (hosts can't update it), so shared links keep working.
--
-- Privacy: a slug is guessable, so it only resolves for PUBLIC, non-draft webinars. Unlisted webinars stay
-- reachable only through their unguessable /register/<id> link; switching a webinar to unlisted stops its
-- slug from resolving. Registering still goes through register_for_webinar with the webinar id, so approval,
-- capacity, required answers and status checks are unchanged.
--
-- Rollback: supabase/rollbacks/20261030000000_event_slugs.down.sql

-- ---------------------------------------------------------------------------
-- Slug generation
-- ---------------------------------------------------------------------------

-- "Growth Masterclass: Q&A!" -> "growth-masterclass-q-a". Empty results fall back to "webinar".
create function public.slugify(p_text text)
returns text
language sql
immutable
set search_path = ''
as $$
  select coalesce(
    nullif(btrim(left(regexp_replace(lower(coalesce(p_text, '')), '[^a-z0-9]+', '-', 'g'), 60), '-'), ''),
    'webinar'
  );
$$;

-- First free slug for a title: base, then base-2, base-3, ... One transaction-level lock for all slug
-- generation, so two webinars created at the same moment can't pick the same slug (creation is rare).
create function public.next_webinar_slug(p_title text, p_exclude uuid default null)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_base text := public.slugify(p_title);
  v_slug text := v_base;
  v_n    integer := 1;
begin
  perform pg_advisory_xact_lock(hashtext('public.webinars.slug'));
  while exists (select 1 from public.webinars w where w.slug = v_slug and w.id is distinct from p_exclude) loop
    v_n := v_n + 1;
    v_slug := btrim(left(v_base, 54), '-') || '-' || v_n;
  end loop;
  return v_slug;
end;
$$;

revoke execute on function public.next_webinar_slug(text, uuid) from public, anon, authenticated;

alter table public.webinars add column slug text;

-- Backfill existing webinars, oldest first, without touching updated_at or firing the status triggers.
alter table public.webinars disable trigger user;
do $$
declare
  r record;
begin
  for r in select w.id, w.title from public.webinars w order by w.created_at, w.id loop
    update public.webinars set slug = public.next_webinar_slug(r.title, r.id) where id = r.id;
  end loop;
end;
$$;
alter table public.webinars enable trigger user;

alter table public.webinars
  alter column slug set not null,
  add constraint webinars_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 64);

create unique index webinars_slug_key on public.webinars (slug);

-- The database always picks the slug on insert (a client-sent value is ignored) and keeps it on update.
-- Hosts can't update the column anyway (it isn't in the column grant); this also covers service-role writes.
create function public.webinars_slug_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.slug := public.next_webinar_slug(new.title, new.id);
  else
    new.slug := old.slug;
  end if;
  return new;
end;
$$;

create trigger webinars_slug_guard
  before insert or update of slug on public.webinars
  for each row execute function public.webinars_slug_guard();

-- ---------------------------------------------------------------------------
-- Public lookup by slug (public, non-draft webinars only)
-- ---------------------------------------------------------------------------

create function public.get_public_webinar_by_slug(p_slug text)
returns table (
  id                uuid,
  title             text,
  description       text,
  starts_at         timestamptz,
  duration_minutes  integer,
  timezone          text,
  status            public.webinar_status,
  requires_approval boolean,
  host_name         text,
  is_full           boolean,
  custom_fields     jsonb,
  registered_count  integer
)
language sql
stable
security definer
set search_path = ''
as $$
  select g.*
  from public.webinars w
  cross join lateral public.get_public_webinar(w.id) g
  where w.slug = lower(btrim(p_slug))
    and w.visibility = 'public'
    and w.status <> 'draft';
$$;

revoke execute on function public.get_public_webinar_by_slug(text) from public;
grant execute on function public.get_public_webinar_by_slug(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- My events: the caller's own registrations with public webinar details
-- ---------------------------------------------------------------------------

-- Registrants can already read their own registration rows (RLS), but not the webinars table, so this joins
-- the public details for them. Only rows where registrations.user_id = auth.uid(); drafts are left out.
create function public.list_my_registrations()
returns table (
  registration_id     uuid,
  registration_status public.registration_status,
  registered_at       timestamptz,
  webinar_id          uuid,
  title               text,
  starts_at           timestamptz,
  duration_minutes    integer,
  timezone            text,
  webinar_status      public.webinar_status,
  host_name           text
)
language sql
stable
security definer
set search_path = ''
as $$
  select r.id, r.status, r.created_at, w.id, w.title, w.starts_at, w.duration_minutes, w.timezone, w.status, p.full_name
  from public.registrations r
  join public.webinars w on w.id = r.webinar_id
  join public.profiles p on p.id = w.host_id
  where auth.uid() is not null
    and r.user_id = auth.uid()
    and w.status <> 'draft'
  order by w.starts_at desc;
$$;

revoke execute on function public.list_my_registrations() from public, anon;
grant execute on function public.list_my_registrations() to authenticated;
